import attr

@attr.s(slots=True)
class MyClass:
    a = attr.ib()
    b = attr.ib()

obj = MyClass(a=1, b=2)
print(f"Initial: {obj}")

# Simulate unpickling a tuple state
try:
    obj.__setstate__((10, 20))
    print(f"After __setstate__ with tuple: {obj}")
    print(f"a: {obj.a}, b: {obj.b}")
except AttributeError as e:
    print(f"Caught expected AttributeError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")

